package donut

import (
	"encoding/json/v2"
	"errors"
	"os"
	"strings"
)

// Tokenizer decodes the token ids generated by a Donut model, it reads the vocabulary of a Hugging Face tokenizer.json (sentencepiece unigram)
type Tokenizer struct {
	pieces   []string
	ids      map[string]int64
	special  map[int64]bool
	BosID    int64
	PadID    int64
	EosID    int64
	UnkID    int64
	VocabLen int
}

type tokenizerFile struct {
	AddedTokens []struct {
		ID      int64  `json:"id"`
		Content string `json:"content"`
		Special bool   `json:"special"`
	} `json:"added_tokens"`
	Model struct {
		Type  string           `json:"type"`
		Vocab [][2]jsonAnyText `json:"vocab"`
	} `json:"model"`
}

// jsonAnyText accepts a json string or number (the unigram vocabulary is a list of [piece, score] pairs)
type jsonAnyText string

// UnmarshalJSON implements the json unmarshaler interface
func (t *jsonAnyText) UnmarshalJSON(data []byte) error {
	var text string

	if err := json.Unmarshal(data, &text); err == nil {
		*t = jsonAnyText(text)
		return nil
	}

	*t = jsonAnyText(data)
	return nil
}

// LoadTokenizer reads a Hugging Face tokenizer.json file
func LoadTokenizer(path string) (*Tokenizer, error) {
	content, err := os.ReadFile(path)

	if err != nil {
		return nil, err
	}

	var file tokenizerFile

	if err := json.Unmarshal(content, &file); err != nil {
		return nil, err
	}

	if file.Model.Type != "Unigram" {
		return nil, errors.New("only unigram tokenizers are supported")
	}

	size := len(file.Model.Vocab)

	for _, token := range file.AddedTokens {
		size = max(size, int(token.ID)+1)
	}

	tokenizer := &Tokenizer{
		pieces:   make([]string, size),
		ids:      make(map[string]int64, size),
		special:  make(map[int64]bool),
		VocabLen: size,
	}

	for id, entry := range file.Model.Vocab {
		tokenizer.pieces[id] = string(entry[0])
		tokenizer.ids[string(entry[0])] = int64(id)
	}

	for _, token := range file.AddedTokens {
		tokenizer.pieces[token.ID] = token.Content
		tokenizer.ids[token.Content] = token.ID

		if token.Special {
			tokenizer.special[token.ID] = true
		}
	}

	var exists bool

	if tokenizer.BosID, exists = tokenizer.ids["<s>"]; !exists {
		return nil, errors.New("tokenizer has no <s> token")
	}

	if tokenizer.PadID, exists = tokenizer.ids["<pad>"]; !exists {
		return nil, errors.New("tokenizer has no <pad> token")
	}

	if tokenizer.EosID, exists = tokenizer.ids["</s>"]; !exists {
		return nil, errors.New("tokenizer has no </s> token")
	}

	if tokenizer.UnkID, exists = tokenizer.ids["<unk>"]; !exists {
		return nil, errors.New("tokenizer has no <unk> token")
	}

	return tokenizer, nil
}

// TokenID returns the id of a single token (e.g. the task prompt "<s_receipt>")
func (t *Tokenizer) TokenID(token string) (int64, bool) {
	id, exists := t.ids[token]
	return id, exists
}

// Decode returns the text of the token ids, the end of sequence and padding tokens are removed, other added tokens (e.g. "<s_total>") are kept
func (t *Tokenizer) Decode(ids []int64) string {
	var builder strings.Builder

	for _, id := range ids {
		if id < 0 || int(id) >= len(t.pieces) || id == t.EosID || id == t.PadID {
			continue
		}

		builder.WriteString(t.pieces[id])
	}

	return strings.TrimSpace(strings.ReplaceAll(builder.String(), "▁", " "))
}
